<?php

namespace Database\Seeders;

use App\Enums\ProductStatus;
use App\Models\Brand;
use App\Models\Category;
use App\Models\Product;
use App\Models\ProductLine;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

/**
 * Seed le catalogue reel de produits K-beauty importe depuis les fiches
 * fournies par le porteur du projet (session du 2026-08-01). Doit tourner
 * apres BrandSeeder, CategorySeeder et ProductLineSeeder.
 *
 * Chaque entree de $products :
 * - name/description/how_to_use/ingredients : texte tel que fourni, ingredients
 *   null quand la liste INCI n'a pas ete communiquee -> produit laisse en brouillon
 *   (obligation legale cosmetique, voir ProductObserver).
 * - brand/line : slugs (line nullable, gamme au sein de la marque).
 * - categories : slugs, un produit peut en avoir plusieurs.
 * - skinTypes : valeurs App\Enums\SkinType, vide/null si non precise.
 * - variants : liste de [label, priceCents] ; label null = variante par defaut
 *   unique (pas de choix a faire) ; plusieurs entrees = vrai choix (contenance,
 *   teinte, format, parfum) via un ProductOption nomme $optionName.
 */
class ProductSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->products() as $data) {
            $this->createProduct($data);
        }
    }

    /**
     * @param  array<string, mixed>  $data
     */
    private function createProduct(array $data): void
    {
        $brand = Brand::query()->where('slug', $data['brand'])->firstOrFail();
        $line = isset($data['line'])
            ? ProductLine::query()->where('slug', $data['line'])->firstOrFail()
            : null;

        $hasIngredients = ! empty($data['ingredients']);

        // Sluggable ne genere pas le slug automatiquement ici : `name` est
        // traduisible (spatie/laravel-translatable), l'attribut lu par le
        // listener `creating` de Sluggable n'est pas la chaine resolue —
        // meme constat que ProductFactory, qui fournit toujours le slug
        // explicitement plutot que de compter sur l'auto-generation.
        $slug = Str::slug($data['name']);

        if (Product::query()->where('slug', $slug)->exists()) {
            return;
        }

        /** @var Product $product */
        $product = Product::query()->create([
            'brand_id' => $brand->id,
            'product_line_id' => $line?->id,
            'name' => $data['name'],
            'slug' => $slug,
            'short_description' => $data['shortDescription'] ?? null,
            'description' => $data['description'],
            'ingredients_inci' => $data['ingredients'] ?? null,
            'how_to_use' => $data['howToUse'] ?? null,
            'skin_types' => $data['skinTypes'] ?? null,
            'status' => $hasIngredients ? ProductStatus::Published : ProductStatus::Draft,
            'published_at' => $hasIngredients ? now() : null,
        ]);

        $categoryIds = Category::query()->whereIn('slug', $data['categories'])->pluck('id');
        $product->categories()->sync($categoryIds);

        $this->createVariants($product, $data['variants'], $data['optionName'] ?? null);
    }

    /**
     * @param  list<array{label: string|null, priceCents: int}>  $variants
     */
    private function createVariants(Product $product, array $variants, ?string $optionName): void
    {
        $option = null;

        if ($optionName !== null && count($variants) > 1) {
            $option = $product->options()->create(['name' => $optionName, 'position' => 0]);
        }

        foreach ($variants as $index => $variant) {
            $sku = Str::upper(Str::slug($product->slug.'-'.($variant['label'] ?? 'default').'-'.($index + 1)));

            $created = $product->variants()->create([
                'sku' => $sku,
                'price_cents' => $variant['priceCents'],
                'currency' => 'EUR',
                'stock_quantity' => 30,
                'is_default' => $index === 0,
                'position' => $index,
            ]);

            if ($option !== null && $variant['label'] !== null) {
                $value = $option->values()->create(['value' => $variant['label'], 'position' => $index]);
                $created->optionValues()->attach($value->id);
            }
        }
    }

